#!/usr/bin/env bash
# Rehace en SERIE lo que murió en el pico de carga: clase 6 (perrito + marcador real +
# animación del = sin encimar + QC + TikTok) y clase 5 (render final + TikTok con perrito).
set -u; cd /home/jose/tiktok; L=scratchpad/_curso/logs; R="$L/V2.txt"; V2="/mnt/c/Users/USUARIO/Downloads/curso_python_v2"
S6=gen_curso_py06_variables; S5=gen_curso_py05_claude_vs_codex
{ .venv/bin/python scratchpad/pon_perrito.py py06 --sin-ensamblar && .venv/bin/python scratchpad/graba_curso.py py06 --solo 2 && .venv/bin/python scratchpad/rehacer_escena.py $S6 1 --sin-ensamblar && .venv/bin/python scratchpad/rehacer_escena.py $S6 --solo-ensamblar && rm -f videos/${S6}_final.mp4 && .venv/bin/python -m autoedit.cli videos/$S6.mp4 --render && cp videos/${S6}_final.mp4 "$V2/clase06_variables.mp4" && echo "  corregida py06 (perrito, marcador real, animacion) $(date +%H:%M)" >> "$R" && bash scratchpad/_curso/posproduce.sh py06; } > "$L/cadena6.log" 2>&1
{ rm -f videos/${S5}_final.mp4 && .venv/bin/python -m autoedit.cli videos/$S5.mp4 --render && cp videos/${S5}_final.mp4 "$V2/clase05_claude_vs_codex.mp4" && echo "  render con perrito py05 $(date +%H:%M)" >> "$R" && timeout 400 .venv/bin/python scratchpad/borra_tiktok.py "4 sep, 19:00" "$(head -c 22 "$V2/clase05_claude_vs_codex_copy.txt")" && sleep 4 && timeout 900 .venv/bin/python scratchpad/subir_tiktok.py subir 'C:\Users\USUARIO\Downloads\curso_python_v2\clase05_claude_vs_codex.mp4' "$V2/clase05_claude_vs_codex_copy.txt" 2026-09-04 19:00 && echo "  TikTok re-reemplazada (perrito) py05 $(date +%H:%M)" >> "$R"; } > "$L/cadena5.log" 2>&1
